#include "workshop_practice.h"
#include <cassert>
#include <iostream>
using namespace workbench;
struct Bench {
    Json info;ArmoryPractice p;PracticeSettings settings;PracticeFrame f;std::vector<Part> parts;std::uint64_t serial{};
    Bench(std::string root,std::string name,bool empty=false,int reserve=-1,int loaded=-1){std::ifstream file(root+"/"+name+".parts.json");file>>info;if(reserve>=0)info["practice"]["reserve"]=reserve;if(loaded>=0)info["practice"]["initial_loaded"]=loaded;for(auto const& row:info.at("parts")){Part x;x.id=row.at("id");x.volume.local.position=vector(row.at("position"));x.volume.radius=row.at("radius");x.volume.snap_distance=.2;parts.push_back(x);}seed_workshop_poses(parts,info);p.configure(info.at("practice"));f.time_ns=1'000'000'000;f.head={{0,1.7,0},{}};f.eye=f.head;for(auto& c:f.controllers)c.valid=true;p.reset({{0,1,-.5},{}},f.head,empty);p.resume(settings,1);at(0,1);tick();}
    void tick(int n=1,bool render=true){for(int i=0;i<n;++i){f.time_ns+=10'000'000;p.step(f,parts);if(render)p.acknowledge_render(++serial);}}
    void at(unsigned i,unsigned side=0){auto w=compose(p.gun(),compose(p.delta(parts[i].id),parts[i].poses[side].wrist_in_object));f.controllers[side].grip=compose(w,inverse(controller_wrist_mount(side,side==1&&p.main_held())));}
    void take(){f.controllers[1].squeeze=0;tick();at(0,1);f.controllers[1].aim=p.gun();f.controllers[1].aim_valid=true;f.controllers[1].squeeze=1;tick();assert(p.main_held());}
    void release(){f.controllers[0].squeeze=f.controllers[0].trigger=0;tick();}
    void grab(unsigned i){release();at(i);tick();f.controllers[0].squeeze=1;tick();if(p.off_part()!=int(i)){std::cerr<<"grab "<<i<<" got "<<p.off_part()<<" "<<p.status()<<"\n";assert(false);}}
    void move(V delta,int n=20){auto start=f.controllers[0].grip.position;for(int i=1;i<=n;++i){f.controllers[0].grip.position=add(start,mul(delta,double(i)/n));tick();}tick(3);}
    void supply(){release();f.controllers[0].grip=p.shoulder();tick();f.controllers[0].squeeze=1;tick();assert(p.ammo_held());}
    void insert(){auto dir=vector(info["practice"]["insertion_axis"]);P target=compose(p.gun(),compose(p.delta("mechanism"),{vector(info["practice"]["feed"]),{}}));if(info["practice"]["kind"]!="revolver")target=compose(p.gun(),{vector(info["practice"]["feed"]),{}});auto local=relative(P{vector(info["practice"]["feed"]),{}},parts[2].poses[0].wrist_in_object);auto pose_for=[&](double distance){P a=target;a.position=sub(a.position,rotate(target.orientation,mul(dir,distance)));return compose(compose(a,local),inverse(controller_wrist_mount(0,false)));};auto start=f.controllers[0].grip;auto goal=pose_for(.15);for(int i=1;i<=100;++i){f.controllers[0].grip=mix(start,goal,i/100.);tick();}start=goal;goal=pose_for(.03);for(int i=1;i<=40;++i){f.controllers[0].grip=mix(start,goal,i/40.);tick();}tick(30);if(p.ammo_held())std::cerr<<info["practice"]["id"]<<" insertion stalled "<<p.status()<<"\n";assert(!p.ammo_held());}
};
int main(int argc,char** argv){assert(argc==2);std::string root=argv[1];
    {Bench b(root,"Boltock");b.take();b.grab(3);b.move({-.06,0,0});b.release();assert(!b.p.chambered());unsigned before=b.p.loaded(),reserve=b.p.reserve();b.supply();assert(b.p.held_quantity()==6-before);assert(b.info["practice"]["reload_item"]=="cylinder");assert(!b.p.bone_visible(b.info["practice"]["cylinder_bone"].get<unsigned>()));b.insert();assert(b.p.loaded()==6&&b.p.reserve()==reserve-(6-before));assert(b.p.bone_visible(b.info["practice"]["cylinder_bone"].get<unsigned>()));assert(!b.p.chambered());b.release();b.at(3);b.tick();b.f.controllers[0].squeeze=1;b.tick();assert(b.p.chambered());b.f.controllers[1].trigger=1;b.tick();assert(b.p.shots()==1&&b.p.loaded()==5);}
    {Bench b(root,"Gnasher");b.take();auto before=b.p.loaded();b.supply();b.insert();assert(b.p.loaded()==before+1&&!b.p.chambered());b.grab(1);auto start=b.f.controllers[1].grip.position;for(int i=1;i<=20;++i){b.f.controllers[1].grip.position=add(start,{0,-.16*i/20,0});b.tick();}for(int i=1;i<=20;++i){b.f.controllers[1].grip.position=add(start,{0,-.16+.16*i/20,0});b.tick();}assert(b.p.chambered()&&b.p.cycles()==1);b.f.controllers[1].trigger=1;b.tick();assert(b.p.shots()==1&&!b.p.chambered());b.tick(100);assert(b.p.shots()==1);}
    {Bench b(root,"Torque_Bow",true);b.take();b.supply();b.insert();assert(b.p.loaded()==1);b.f.controllers[1].trigger=1;b.tick(30);assert(b.p.shots()==0);b.f.controllers[1].trigger=0;b.tick();assert(b.p.shots()==1&&b.p.loaded()==0);}
    {Bench b(root,"Hammerburst",true);b.take();b.grab(3);b.move({0,0,.08});b.release();b.grab(2);b.move({0,-.06,0});b.release();b.supply();b.insert();assert(b.p.loaded()==78&&b.p.reserve()==624);b.grab(3);b.move({0,0,-.08});b.release();assert(b.p.chambered());b.f.controllers[1].trigger=1;b.tick();assert(b.p.shots()==1);}
    {Bench b(root,"Boomshot",true);assert(b.p.guide_stage()==0);b.take();assert(b.p.guide_stage()==3);b.grab(3);b.move({0,0,.11});b.release();assert(b.p.guide_stage()==4);b.supply();assert(b.p.guide_stage()==2);b.insert();assert(b.p.loaded()==1&&b.p.guide_stage()==3);b.grab(3);b.move({0,0,-.11});b.release();assert(b.p.chambered());b.f.controllers[1].trigger=1;b.tick();assert(b.p.shots()==1);}
    {Bench b(root,"Longshot",true);b.take();b.grab(3);b.move({0,0,.13});assert(b.p.guide_stage()==3); // A straight pull cannot bypass bolt lift.
     b.release();b.grab(3);auto initial=b.f.controllers[0].grip.orientation;b.f.controllers[0].grip.orientation=v::multiply(initial,axis({0,0,1},.65));b.tick(3);b.move({0,0,.13});b.release();assert(b.p.guide_stage()==4);b.supply();b.insert();b.grab(3);b.move({0,0,-.13});b.f.controllers[0].grip.orientation=initial;b.tick(4);b.release();assert(b.p.chambered());b.f.controllers[1].trigger=1;b.tick();assert(b.p.shots()==1&&!b.p.chambered());}
    {Bench b(root,"COG_Pistol",true);b.take();b.grab(2);b.move({0,-.06,0});b.release();b.supply();b.insert();assert(!b.p.chambered());b.grab(3);b.move({0,0,.02});b.release();b.tick(30);assert(!b.p.chambered());b.grab(3);b.move({0,0,.10});b.release();b.tick(30);assert(b.p.chambered());b.f.controllers[1].trigger=1;b.tick();assert(b.p.shots()==1);}
    {Bench b(root,"Hammer_of_Dawn");b.take();b.f.controllers[1].trigger=1;b.tick();assert(b.p.beam_active());auto n=b.p.shots();b.f.focused=false;b.tick();assert(!b.p.main_held()&&!b.p.beam_active());b.f.focused=true;b.tick();assert(!b.p.main_held()&&b.p.shots()==n);}
    {Bench b(root,"Troika_turret");b.take();b.f.controllers[1].trigger=1;b.tick();assert(b.p.shots()==0);b.grab(1);b.tick(20);assert(b.p.shots()>0);b.release();auto n=b.p.shots();b.tick(20);assert(b.p.shots()==n);}
    for(auto name:{"Frag_Grenade","Smoke_Grenade"}){Bench b(root,name);b.take();b.f.controllers[1].valid=false;b.tick();assert(b.p.throws().empty());b.f.controllers[1].valid=true;b.take();b.f.controllers[1].grip.position.x+=.03;b.tick();b.f.controllers[1].squeeze=0;b.tick();assert(b.p.throws().size()==1&&b.p.shots()==1);b.tick(10);assert(b.p.throws().size()==1);}
    {Bench b(root,"Torque_Bow");b.take();b.f.controllers[1].trigger=1;b.tick(20);b.f.focused=false;b.tick();b.f.focused=true;b.f.controllers[1].trigger=0;b.tick();assert(b.p.shots()==0);}
    {Bench b(root,"Boltock",false,2,2);b.take();b.grab(3);b.move({-.06,0,0});b.release();b.supply();assert(b.p.held_quantity()==2);b.insert();assert(b.p.loaded()==4&&b.p.reserve()==0);b.tick(100);assert(b.p.loaded()==4&&b.p.reserve()==0);b.release();b.at(3);b.tick();b.f.controllers[0].squeeze=1;b.tick();assert(b.p.chambered());}
    {Bench b(root,"COG_Pistol",true);b.take();b.grab(2);b.move({0,-.06,0});b.release();b.supply();b.insert();b.grab(3);b.f.controllers[0].grip.position.z+=.10;b.tick(1,false);b.f.controllers[0].valid=false;b.tick();b.tick(30);assert(!b.p.chambered());}
    for(auto name:{"Boltock","COG_Pistol"}){Bench b(root,name);b.take();b.parts[1].poses[0].wrist_in_object.position.x+=.015;b.grab(1);assert(b.p.off_part()==1&&b.p.hand_parts()[0]==1);auto target=compose(b.p.gun(),b.parts[1].poses[0].wrist_in_object);assert(length(sub(b.p.hand_wrists()[0].position,target.position))<1e-6);auto before=b.p.gun().orientation;b.move({.02,.01,0});assert(rotation_error(before,b.p.gun().orientation)<1e-5);}

    std::cout<<"PASS: eleven non-Lancer CPU flows, fresh input/loss gates, video reload rules and yellow-guide stages.\n";
}
